Looking at the demo pair, I can see the transformation rule:
- Background value (1 in demo, 2 in test) stays as is unless between special values
- Special values (4 in demo, 6 in test) stay as is
- Cells between any two special values in the same row OR column get filled with 3

The logic is: for every pair of special-value cells, if they share a row or column, fill all intermediate cells with 3.

```python
def transform(grid):
    from collections import Counter

    # Get all unique values
    all_values = [val for row in grid for val in row]
    counts = Counter(all_values)

    # Background is most frequent, special is less frequent
    bg = max(counts, key=counts.get)
    values = list(set(all_values))
    special = [v for v in values if v != bg][0]

    rows = len(grid)
    cols = len(grid[0])

    # Copy grid for output
    output = [row[:] for row in grid]

    # Find all special positions
    special_pos = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == special:
                special_pos.append((r, c))

    # Fill between special cells in same row or column
    for i in range(len(special_pos)):
        for j in range(i + 1, len(special_pos)):
            r1, c1 = special_pos[i]
            r2, c2 = special_pos[j]

            if r1 == r2:
                # Horizontal fill
                min_c, max_c = min(c1, c2), max(c1, c2)
                for c in range(min_c + 1, max_c):
                    if output[r1][c] == bg:
                        output[r1][c] = 3
            elif c1 == c2:
                # Vertical fill
                min_r, max_r = min(r1, r2), max(r1, r2)
                for r in range(min_r + 1, max_r):
                    if output[r][c1] == bg:
                        output[r][c1] = 3

    return output
